// 严格原参数解码与借口分派，前端不能靠更换kind套用另一个宽松公共guard。
#include "private_shop_liquidation_boundary.hpp"
#include "resident/domains/local_economy/economic_payload_guard.hpp"
namespace hanmo::resident {
Status validate_private_shop_liquidation_pair(bool enabled,const std::vector<std::pair<StableId,StableId>>& modules){
    std::map<StableId,StableId> selected;for(const auto& m:modules)if((enabled||m.first==private_shop_liquidation_module||m.first=="task_shop_order_estate_cancellations")&&(m.first==private_shop_liquidation_module||m.first=="task_shop_order_estate_cancellations"||m.first=="private_shops"||m.first=="task_shop_orders"||m.first=="family_life"||m.first=="task_message_notices"||m.first=="task_message_handoffs")){if(!selected.emplace(m).second||(m.first=="task_message_handoffs"?(m.second!="1"&&m.second!="2"):m.second!="1"))return common_failure("PrivateShopLiquidationPairMismatch",m.first);}
    const bool own=selected.count(private_shop_liquidation_module),orders=selected.count("task_shop_order_estate_cancellations");if(!enabled)return own||orders?common_failure("PrivateShopLiquidationPairMismatch"):common_success();for(const auto* name:{private_shop_liquidation_module,"task_shop_order_estate_cancellations","private_shops","task_shop_orders","family_life","task_message_notices","task_message_handoffs"})if(!selected.count(name))return common_failure("PrivateShopLiquidationDependencyRequired",name);return common_success();
}
StableId private_shop_liquidation_command_kind(const PrivateShopLiquidationCommand& command){return std::visit([](const auto& c)->StableId{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PrivateShopAppointExecutor>)return "private_shop_appoint_executor";else if constexpr(std::is_same_v<T,PrivateShopAcceptExecutorship>)return "private_shop_accept_executorship";else if constexpr(std::is_same_v<T,PrivateShopRevokeExecutor>)return "private_shop_revoke_executor";else return "private_shop_estate_close";},command);}
Outcome<PrivateShopLiquidationCommand> decode_private_shop_liquidation_command(const StableId& kind,const BoundaryValue& params){auto unique=validate_economic_payload_fields(params);if(!unique.ok)return {false,{},unique.error};try{using namespace boundary;
    if(kind=="private_shop_appoint_executor"||kind=="private_shop_accept_executorship"){fields(params,{"shop_id","policy_id"},{},kind);auto shop=get_string(params,"shop_id",kind),policy=get_string(params,"policy_id",kind);if(shop.empty()||policy.empty())fail("InvalidPrivateShopExecutorCommand",kind);if(kind=="private_shop_appoint_executor")return {true,PrivateShopAppointExecutor{shop,policy},{}};return {true,PrivateShopAcceptExecutorship{shop,policy},{}};}
    if(kind=="private_shop_revoke_executor"){fields(params,{"mandate_fact_id","decision"},{},kind);auto id=get_string(params,"mandate_fact_id",kind),decision=get_string(params,"decision",kind);if(id.empty()||(decision!="revoke"&&decision!="withdraw"))fail("InvalidPrivateShopExecutorDecision",kind);return {true,PrivateShopRevokeExecutor{id,decision},{}};}
    if(kind=="private_shop_estate_close"){fields(params,{"shop_id","mandate_fact_id","death_notice_binding_fact_id"},{},kind);PrivateShopEstateClose out{get_string(params,"shop_id",kind),get_string(params,"mandate_fact_id",kind),get_string(params,"death_notice_binding_fact_id",kind)};if(out.shop_id.empty()||out.mandate_fact_id.empty()||out.death_notice_binding_fact_id.empty())fail("InvalidPrivateShopEstateClosingCommand",kind);return {true,std::move(out),{}};}
    fail("UnknownPrivateShopLiquidationCommand",kind);
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_private_shop_liquidation_command(const PrivateShopLiquidationCommand& command){using V=BoundaryValue;return std::visit([](const auto& c)->V{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PrivateShopAppointExecutor>||std::is_same_v<T,PrivateShopAcceptExecutorship>)return boundary::obj({{"shop_id",V{c.shop_id}},{"policy_id",V{c.policy_id}}});else if constexpr(std::is_same_v<T,PrivateShopRevokeExecutor>)return boundary::obj({{"mandate_fact_id",V{c.mandate_fact_id}},{"decision",V{c.decision}}});else return boundary::obj({{"shop_id",V{c.shop_id}},{"mandate_fact_id",V{c.mandate_fact_id}},{"death_notice_binding_fact_id",V{c.death_notice_binding_fact_id}}});},command);}
Outcome<PrivateShopLiquidationQuote> preview_private_shop_liquidation_command(const PrivateShopContext& shops,const PrivateShopLiquidationContext& estate,const PrivateShopMeetingContext& meeting,const StableId& actor,const PrivateShopLiquidationCommand& command){
    if(&shops.common!=&estate.common||&shops.state!=&estate.shops||&shops.catalog!=&estate.shop_catalog||shops.phase)return {false,{},common_failure("PrivateShopEstateCandidateMismatch").error};
    // 委任借原店成立史；执行再用具名清算报价核全部未结责任，不能从纯委托账跳过经营前置。
    auto valid=validate_private_shops(shops);if(!valid.ok)return {false,{},valid.error};PrivateShopLiquidationQuote out{shops.common.state().identity,actor,command,{}};
    auto result=std::visit([&](const auto& c)->Status{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PrivateShopEstateClose>){auto q=preview_private_shop_estate_closing(shops,estate,actor,c);if(!q.ok)return {false,{},q.error};out.data=std::move(q.value);}else {auto q=preview_private_shop_executor(estate,meeting,shops.activity,actor,PrivateShopExecutorCommand{c});if(!q.ok)return {false,{},q.error};out.data=std::move(q.value);}return common_success();},command);
    return result.ok?Outcome<PrivateShopLiquidationQuote>{true,std::move(out),{}}:Outcome<PrivateShopLiquidationQuote>{false,{},result.error};
}
BoundaryValue encode_private_shop_liquidation_quote(const PrivateShopLiquidationQuote& q){using V=BoundaryValue;auto terms=std::visit([](const auto& value)->V{using T=std::decay_t<decltype(value)>;if constexpr(std::is_same_v<T,PrivateShopExecutorQuote>)return boundary::obj({{"duration",V{Integer{0}}},{"shop_id",V{value.shop_id}},{"proprietor_actor_id",V{value.proprietor_actor_id}},{"executor_actor_id",V{value.executor_actor_id}},{"scope",V{StableId{"收到原死亡文书后，只清理本店未交订单和归还剩余财货；不授予继产、新营业或挪用权。"}}}});else {V::Array lots;for(const auto& lot:value.assets.stock_lots)lots.push_back(boundary::obj({{"item_id",V{lot.item_id}},{"quantity",V{lot.quantity}}}));return boundary::obj({{"duration",V{Integer{0}}},{"shop_id",V{value.command.shop_id}},{"proprietor_actor_id",V{value.assets.actor_id}},{"executor_actor_id",V{value.actor_id}},{"mandate_fact_id",V{value.authority.mandate_fact_id}},{"death_notice_binding_fact_id",V{value.authority.death_notice_binding_fact_id}},{"return_wallet_id",V{value.assets.to_wallet_id}},{"return_inventory_id",V{value.assets.to_inventory_id}},{"returned_cash",V{value.assets.returned_cash}},{"returned_lots",V{std::move(lots)}}});}},q.data);return boundary::obj({{"ok",V{true}},{"kind",V{private_shop_liquidation_command_kind(q.command)}},{"actor_id",V{q.actor_id}},{"params",encode_private_shop_liquidation_command(q.command)},{"terms",std::move(terms)}});}
Status validate_private_shop_liquidation_notice_routes(const PrivateShopLiquidationCatalog& catalog,const TaskCatalog& tasks,const TaskMessageNoticeCatalog& notices){
    if(catalog.version!=1||notices.version!=1)return common_failure("PrivateShopEstateNoticeProfileMismatch");
    for(const auto& row:catalog.policies.rows()){const auto& p=row.second;bool found=false;for(const auto& binding:notices.bindings.rows()){if(binding.first!=binding.second.offer_id)return common_failure("PrivateShopEstateNoticeRouteMismatch",binding.first);if(binding.second.decedent_actor_id!=p.proprietor_actor_id)continue;const auto* offer=tasks.offers.find(binding.second.offer_id);if(offer&&offer->template_id=="message"&&offer->goal.receiver_actor==p.executor_actor_id&&offer->issuer.kind==Owner::Kind::actor&&offer->issuer.id!=p.proprietor_actor_id&&offer->issuer.id!=p.executor_actor_id)found=true;}if(!found)return common_failure("PrivateShopEstateNoticeRouteRequired",row.first);}
    return common_success();
}
Outcome<std::optional<PrivateShopLiquidationCatalog>> decode_private_shop_liquidation_profile(const BoundaryValue& scenario,const std::vector<StableId>& caps){
    auto unique=validate_economic_payload_fields(scenario);if(!unique.ok)return {false,{},unique.error};const auto* dynamic=scenario.find("dynamic_world");const auto* block=dynamic?dynamic->find(private_shop_liquidation_module):nullptr;if(!block)return {true,std::nullopt,{}};
    try{for(const auto* cap:{"private_shop_liquidations_v1","private_shops_v1","family_life_v1","task_death_notices_v1","task_shop_orders_v1"})if(std::find(caps.begin(),caps.end(),cap)==caps.end())boundary::fail("PrivateShopLiquidationCapabilityRequired",cap);if(boundary::get_string(scenario,"task_shop_order_profile","")!="private_shop_orders_v1")boundary::fail("PrivateShopLiquidationOrderProfileRequired",private_shop_liquidation_module);auto shops=decode_private_shop_profile(scenario,caps);if(!shops.ok)return {false,{},shops.error};if(!shops.value)boundary::fail("PrivateShopLiquidationShopProfileRequired",private_shop_liquidation_module);const auto* life=scenario.find("family_life");if(!life)boundary::fail("PrivateShopLiquidationLifeProfileRequired",private_shop_liquidation_module);auto death=decode_family_death_policy(*life);if(!death.ok)return {false,{},death.error};if(!death.value.enabled)boundary::fail("PrivateShopLiquidationLifeProfileRequired",private_shop_liquidation_module);auto notices=decode_task_message_notice_catalog(scenario,caps);if(!notices.ok)return {false,{},notices.error};if(!notices.value)boundary::fail("PrivateShopLiquidationNoticeProfileRequired",private_shop_liquidation_module);auto catalog=decode_private_shop_liquidation_catalog(*block);if(!catalog.ok)return {false,{},catalog.error};if(catalog.value.policies.empty())boundary::fail("PrivateShopExecutorPolicyRequired",private_shop_liquidation_module);return {true,std::optional<PrivateShopLiquidationCatalog>{std::move(catalog.value)},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}
}
}
